//! Step-1 gate: prove blocking works before any UI exists.
//! Run with: cargo test --manifest-path rust/Cargo.toml -- --nocapture

use shieldtube::engine::ShieldEngine;

/// Generated by scripts/fetch-lists.sh from the pinned uBO source. This test
/// proves the generated resources parse in adblock 0.13.5 and that a real
/// `+js(set, ...)` rule resolves to the uBO registry rather than being dropped.
const BUNDLED_RESOURCES: &str = include_str!("../../app/src/main/assets/lists/resources.json");

const BASE_RULES: &str = "||doubleclick.net^\n\
||googlesyndication.com^\n\
||ads.example.org^$script\n\
youtube.com##.video-ads\n\
youtube.com##ytd-display-ad-renderer\n";

fn engine_with(rules: &str, resources: serde_json::Value) -> ShieldEngine {
    let json = serde_json::json!({
        "lists": [{
            "name": "test.txt",
            "text": rules,
            "format": "standard",
            "trusted": true
        }],
        "resources": resources
    })
    .to_string();
    ShieldEngine::create(&json).expect("engine must build")
}

#[test]
fn blocks_a_known_ad_url() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    assert!(
        engine.check_request(
            "https://doubleclick.net/ads/banner.js",
            "https://www.youtube.com/tv",
            "script"
        ),
        "doubleclick must be blocked"
    );
    assert!(
        engine.check_request(
            "https://googlesyndication.com/pagead/js/adsbygoogle.js",
            "https://www.youtube.com/tv",
            "script"
        ),
        "googlesyndication must be blocked"
    );
}

#[test]
fn does_not_block_first_party_youtube_assets() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    assert!(!engine.check_request(
        "https://www.youtube.com/s/desktop/abc/js/base.js",
        "https://www.youtube.com/tv",
        "script"
    ));
}

#[test]
fn request_type_is_respected() {
    // A wrong requestType produces false positives (preamble §3 layer 1).
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    let url = "https://ads.example.org/creative.js";
    assert!(engine.check_request(url, "https://www.youtube.com/tv", "script"));
    assert!(!engine.check_request(url, "https://www.youtube.com/tv", "image"));
}

#[test]
fn player_endpoint_is_never_blocked_even_by_a_matching_rule() {
    let rules = "||youtube.com/youtubei/v1/player^\n||youtube.com/youtubei/v1/next^\n";
    let engine = engine_with(rules, serde_json::json!([]));
    assert!(!engine.check_request(
        "https://www.youtube.com/youtubei/v1/player?key=abc",
        "https://www.youtube.com/tv",
        "xhr"
    ));
    assert!(!engine.check_request(
        "https://www.youtube.com/youtubei/v1/next?key=abc",
        "https://www.youtube.com/tv",
        "xhr"
    ));
}

#[test]
fn malformed_url_fails_open() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    assert!(!engine.check_request("not a url", "https://www.youtube.com/tv", "script"));
}

#[test]
fn cosmetic_for_emits_the_pinned_0_13_5_schema() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    let json: serde_json::Value =
        serde_json::from_str(&engine.cosmetic_for("https://www.youtube.com/watch?v=abc"))
            .expect("cosmeticFor returns valid JSON");

    // Lead condition 5: assert the exact field set of the pinned crate.
    assert!(json.get("hide_selectors").is_some());
    assert!(json.get("procedural_actions").is_some());
    assert!(json.get("exceptions").is_some());
    assert!(json.get("injected_script").is_some());
    assert!(json.get("generichide").is_some());
    assert!(
        json.get("style_selectors").is_none(),
        "adblock 0.13.5 has no style_selectors; if this fails, the pin changed"
    );

    let hide = json["hide_selectors"].as_array().expect("array");
    assert!(hide.iter().any(|v| v == ".video-ads"));
    assert!(hide.iter().any(|v| v == "ytd-display-ad-renderer"));
    assert_eq!(json["generichide"], false);
}

#[test]
fn scriptlet_args_are_already_templated_by_adblock_rust() {
    // "window.__stTest = '{{1}}';"
    let resources = serde_json::json!([{
        "name": "st-test.js",
        "aliases": [],
        "kind": "template",
        "content": "d2luZG93Ll9fc3RUZXN0ID0gJ3t7MX19Jzs=",
        "dependencies": []
    }]);
    let rules = "youtube.com##+js(st-test.js, hello)\n";
    let engine = engine_with(rules, resources);
    let json: serde_json::Value =
        serde_json::from_str(&engine.cosmetic_for("https://www.youtube.com/watch?v=abc"))
            .expect("valid JSON");
    let injected = json["injected_script"].as_str().unwrap_or("");
    assert!(
        injected.contains("hello"),
        "engine must substitute {{1}} itself: {injected}"
    );
    assert!(
        !injected.contains("{{1}}"),
        "no unresolved template placeholders may remain: {injected}"
    );
}

#[test]
fn add_lists_replace_rebuilds_the_engine() {
    let empty = ShieldEngine::create(r#"{"lists":[],"resources":[]}"#).unwrap();
    assert!(!empty.check_request(
        "https://doubleclick.net/a.js",
        "https://www.youtube.com/tv",
        "script"
    ));

    let payload = serde_json::json!({
        "replace": true,
        "lists": [{
            "name": "test.txt", "text": "||doubleclick.net^",
            "format": "standard", "trusted": false
        }]
    })
    .to_string();
    assert!(empty.add_lists(&payload).is_ok());
    assert!(empty.check_request(
        "https://doubleclick.net/a.js",
        "https://www.youtube.com/tv",
        "script"
    ));
}

#[test]
fn invalid_payload_is_rejected_not_panicking() {
    assert!(ShieldEngine::create("not json").is_err());
    assert!(ShieldEngine::create("{}").is_ok());
}

#[test]
fn generated_ubo_scriptlets_resolve_pinned_rules() {
    let resources: serde_json::Value =
        serde_json::from_str(BUNDLED_RESOURCES).expect("bundled resources.json parses");
    assert!(resources.as_array().is_some_and(|r| r.len() > 90));
    let rules = "youtube.com##+js(set, shieldtubeUboTest, 1)\n";
    let engine = engine_with(rules, resources);
    let json: serde_json::Value =
        serde_json::from_str(&engine.cosmetic_for("https://www.youtube.com/watch?v=abc"))
            .expect("valid cosmetic JSON");
    let injected = json["injected_script"].as_str().unwrap_or("");
    assert!(
        injected.contains("ShieldTubeUboRegistry"),
        "uBO registry dependency must be injected: {injected}"
    );
    assert!(
        injected.contains("shieldtubeUboTest"),
        "real uBO `set` scriptlet must receive the rule argument: {injected}"
    );
    assert!(
        !injected.contains("{{1}}"),
        "no unresolved template placeholders may remain: {injected}"
    );
}

// ---------------------------------------------------------------------------
// Case-normalisation: the engine consulted adblock 0.13.5 with the URL exactly
// as the WebView handed it over. The crate lower-cases the scheme but NOT an
// all-ASCII host (url_parser/parser.rs parse_host writes `{host_str}` verbatim
// and only calls idna::domain_to_ascii for non-ASCII hosts), and
// `cpt_match_type` is an exact-case `match`. Both were exploitable: a list rule
// and a request that differ only in host case did not match, and "SCRIPT"
// became RequestType::Other.
// ---------------------------------------------------------------------------

#[test]
fn host_case_does_not_bypass_a_blocking_rule() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    for url in [
        "https://doubleclick.net/ads/banner.js",
        "HTTPS://doubleclick.net/ads/banner.js",
        "https://DOUBLECLICK.NET/ads/banner.js",
        "HTTPS://DOUBLECLICK.NET/ads/banner.js",
        "Https://DoubleClick.Net/ads/banner.js",
    ] {
        assert!(
            engine.check_request(url, "https://www.youtube.com/tv", "script"),
            "host case must not bypass the rule: {url}"
        );
    }
}

#[test]
fn request_type_case_is_canonicalised() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    for kind in ["script", "SCRIPT", "Script", "ScRiPt"] {
        assert!(
            engine.check_request(
                "https://ads.example.org/creative.js",
                "https://www.youtube.com/tv",
                kind
            ),
            "request type {kind} must be canonicalised to `script`"
        );
    }
}

#[test]
fn player_endpoint_survives_every_case_variant() {
    // A rule that matches the player endpoint in any case, plus the
    // allow-list, which must also be case-insensitive.
    let rules = "||youtube.com/youtubei/v1/player^\n||youtube.com/youtubei/v1/next^\n";
    let engine = engine_with(rules, serde_json::json!([]));
    for url in [
        "https://www.youtube.com/youtubei/v1/player?key=a",
        "HTTPS://WWW.YOUTUBE.COM/YOUTUBEI/V1/PLAYER?KEY=A",
        "https://www.YouTube.com/Youtubei/v1/Player",
        "HTTPS://www.youtube.com/youtubei/v1/NEXT",
    ] {
        assert!(
            !engine.check_request(url, "https://www.youtube.com/tv", "xhr"),
            "player endpoint must never be blocked, not even upper-cased: {url}"
        );
    }
}

#[test]
fn path_case_is_preserved_for_case_sensitive_rules() {
    // Only scheme + authority may be lower-cased; the path must reach the
    // engine byte-for-byte.
    //
    // NOTE on how this is asserted: adblock 0.13.5 compiles plain substring
    // rules case-insensitively, so a verdict-based assertion cannot distinguish
    // "we preserved the path" from "the rule was case-insensitive" — measured,
    // `/Ad_300x250/` matches both `/Ad_300x250/` and `/ad_300x250/` with or
    // without normalisation. The invariant is therefore tested at the unit that
    // implements it: the normaliser itself must leave the path untouched.
    use shieldtube::engine::normalise_scheme_and_host;

    assert_eq!(
        normalise_scheme_and_host("https://CDN.Example.COM/Ad_300x250/X.PNG?a=B#Frag"),
        "https://cdn.example.com/Ad_300x250/X.PNG?a=B#Frag",
        "authority lower-cased, path/query/fragment untouched"
    );
    assert_eq!(
        normalise_scheme_and_host("https://cdn.example.com/Ad_300x250/X.PNG"),
        "https://cdn.example.com/Ad_300x250/X.PNG",
        "already-normal URL must be returned unchanged (no allocation path)"
    );
    assert_eq!(
        normalise_scheme_and_host("MAILTO:Someone@Example.COM"),
        "mailto:Someone@Example.COM",
        "opaque scheme: scheme lower-cased, rest untouched"
    );
    assert_eq!(normalise_scheme_and_host("not a url"), "not a url");
    assert_eq!(normalise_scheme_and_host(""), "");

    // And the engine still honours the rule it was given.
    let engine = engine_with("/Ad_300x250/\n", serde_json::json!([]));
    assert!(engine.check_request(
        "https://cdn.example.com/Ad_300x250/banner.png",
        "https://www.youtube.com/tv",
        "image"
    ));
}

#[test]
fn opaque_and_malformed_schemes_do_not_panic() {
    let engine = engine_with(BASE_RULES, serde_json::json!([]));
    for url in [
        "mailto:a@b.c",
        "data:text/html,<b>x</b>",
        "javascript:alert(1)",
        "http:foo",
        "//cdn.example.com/a.js",
        ":::::",
        "",
        " ",
    ] {
        let verdict = engine.check_request(url, "https://www.youtube.com/tv", "script");
        assert!(!verdict, "must fail open and not panic: {url:?}");
    }
}
